function clientForRedirect(info, redirectUrl) {
    if (info === undefined || !info.redirect_uris.includes(redirectUrl)) {
        return undefined;
    }
    return info;
}
export async function createHostMcpOAuthProvider(args) {
    const store = args.store ?? new FileMcpOAuthStore();
    const redirectUrl = args.redirectUrl ?? MCP_OAUTH_CALLBACK_URL;
    const [fileTokens, fileClient, omitResourceIndicator] = await Promise.all([
        store.loadTokens(args.identifier, args.resourceUrl),
        store.loadClientInformation(args.identifier, args.resourceUrl),
        fetchOmitResourceIndicatorFromPrm(args.resourceUrl),
    ]);
    return new HostMcpOAuthProvider({
        identifier: args.identifier,
        resourceUrl: args.resourceUrl,
        store,
        redirectUrl,
        tokens: fileTokens ?? tokensFromEnv(args.identifier),
        clientInformation: clientForRedirect(fileClient ?? clientIdFromEnv(args.identifier), redirectUrl),
        onRedirect: args.onRedirect,
        omitResourceIndicator,
    });
}
/**
 * Deliberately not `@anysphere/mcp-core/oauth/loopback`, which is the canonical
 * implementation every other Cursor surface shares. `@grok/agent-sdk` publishes to
 * public npm with no private workspace dependencies, and its OAuth state is a
 * bare UUID rather than the payload that module's validator expects.
 */
export async function waitForMcpOAuthCallback(args) {
    const port = args.port ?? MCP_OAUTH_CALLBACK_PORT;
    const path = args.path ?? MCP_OAUTH_CALLBACK_PATH;
    const timeoutMs = args.timeoutMs ?? 5 * 60 * 1000;
    const expectedState = new URL(args.authorizationUrl).searchParams.get("state");
    return new Promise((resolve, reject) => {
        let done = false;
        const finish = (result, error) => {
            if (done) {
                return;
            }
            done = true;
            clearTimeout(timer);
            server.close();
            if (error !== undefined) {
                reject(error);
                return;
            }
            if (result !== undefined) {
                resolve(result);
            }
        };
        const server = createServer((req, res) => {
            if (req.url === "/favicon.ico") {
                res.writeHead(404).end();
                return;
            }
            const url = new URL(req.url ?? "", `http://localhost:${port}`);
            if (url.pathname !== path) {
                res.writeHead(404).end("Not found");
                return;
            }
            const code = url.searchParams.get("code");
            const oauthError = url.searchParams.get("error");
            const state = url.searchParams.get("state") ?? undefined;
            // Without this, any page that can reach the loopback port during a login
            // can inject its own authorization code into the exchange. Ignore what is
            // not ours rather than failing the login: treating a stray request as
            // fatal would let any page cancel a login, and free the port for someone
            // else to bind before the real callback arrives.
            if (state !== (expectedState ?? undefined)) {
                res
                    .writeHead(404, { "content-type": "text/html; charset=utf-8" })
                    .end("<!doctype html><html><body><h1>Not found</h1></body></html>");
                return;
            }
            if (code) {
                res
                    .writeHead(200, { "content-type": "text/html; charset=utf-8" })
                    .end("<!doctype html><html><body><h1>Authorized</h1><p>Return to Agent SDK.</p></body></html>");
                finish({ code, state });
                return;
            }
            res
                .writeHead(400, { "content-type": "text/html; charset=utf-8" })
                .end(`<!doctype html><html><body><h1>Authorization failed</h1><p>${oauthError ?? "missing code"}</p></body></html>`);
            finish(undefined, new Error(`OAuth authorization failed: ${oauthError ?? "missing code"}`));
        });
        const timer = setTimeout(() => {
            finish(undefined, new Error(`Timed out waiting for OAuth callback on http://localhost:${port}${path}`));
        }, timeoutMs);
        server.on("error", (error) => {
            finish(undefined, new Error(`OAuth callback port ${port} failed: ${error instanceof Error ? error.message : String(error)}`));
        });
        server.listen(port, "127.0.0.1");
    });
}
export function openBrowser(url) {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") {
        throw new Error(`Refusing to open non-http(s) authorization URL: ${parsed.protocol}`);
    }
    const href = parsed.href;
    if (process.platform === "darwin") {
        execFile("open", [href], () => undefined);
        return;
    }
    if (process.platform === "win32") {
        // Avoid `cmd /c start` — authorize URLs with `&` are shell-metachar risks.
        execFile("rundll32", ["url.dll,FileProtocolHandler", href], () => undefined);
        return;
    }
    execFile("xdg-open", [href], () => undefined);
}
